import React from "react";
import { useLocation } from "react-router-dom";
import { listings } from "../list";

export default function SearchResultsPage() {
  const location = useLocation();
  const query = new URLSearchParams(location.search).get("query") || "";
  const category = new URLSearchParams(location.search).get("category") || "All";

  // Filter the listings based on query and category
  const filteredListings = Object.entries(listings)
    .flatMap(([key, items]) => (category === "All" || key === category ? items : []))
    .filter((listing) =>
      query ? listing.title.toLowerCase().includes(query.toLowerCase()) : true
    );

  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-3xl font-semibold text-gray-800 mb-6">
        Search Results for "{query}" in "{category}"
      </h1>
      {filteredListings.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {filteredListings.map((listing, index) => (
            <div
              key={index}
              className="border rounded-lg p-4 shadow-md hover:shadow-lg transition-shadow duration-300"
            >
              <img
                src={listing.image}
                alt={listing.title}
                className="w-full h-48 object-cover rounded-md mb-4"
              />
              <h2 className="text-xl font-bold text-gray-800 mb-2">{listing.title}</h2>
              <p className="text-gray-600 mb-4">{listing.description}</p>
              <button className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-700">
                View Details
              </button>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-gray-600">No results found.</p>
      )}
    </div>
  );
}
